/* Our Family Meals PWA, self-contained compressed asset loader */
(async()=>{const b64="";try{const b=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const txt=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text();const [css,data,app]=JSON.parse(txt);const st=document.createElement('style');st.textContent=css;document.head.appendChild(st);for(const src of [data,app]){const el=document.createElement('script');el.textContent=src;document.body.appendChild(el)}}catch(e){document.body.innerHTML='<main style="font-family:sans-serif;padding:30px"><h1>웹앱을 실행할 수 없습니다</h1><p>Chrome 또는 삼성 인터넷 최신 버전에서 다시 시도해 주세요.</p></main>';console.error(e)}})();